/*!40000 ALTER TABLE `early_warning` DISABLE KEYS */;
INSERT INTO `early_warning` VALUES (1,1,'Masa berlaku','> H-180','E0','PKS berlaku 15 November 2025 s.d. 14 November 2030.','Pertahankan monitoring masa berlaku.','Pengelola kerja sama',NULL,'DALAM PROSES','2026-10-04 15:51:07'),(2,1,'Aktivitas/tenggat','TIDAK ADA AKTIVITAS >180 HARI','E2','Implementasi baru tampak pada 2 dari 5 ruang lingkup; 3 ruang lingkup belum memiliki data pelaksanaan.','Susun rencana aksi dan aktivasi ruang lingkup yang belum berjalan.','PIC/pengampu P01','2026-12-31','DALAM PROSES','2026-10-04 15:51:07'),(3,1,'Data/eviden','BELUM LENGKAP SETELAH TENGGAT','E2','Evidence terbatas pada tautan publikasi dan laporan MIC; file eviden baru belum terisi substantif.','Konsolidasikan repository dan minta evidence lengkap per ruang lingkup.','Pengelola + PIC','2026-10-31','DALAM PROSES','2026-10-04 15:51:07'),(4,1,'PIC','TIDAK AKTIF TANPA PENGGANTI','E2','PIC formal internal dan mitra serta mekanisme koordinasi belum terdokumentasi.','Tetapkan PIC dan mekanisme koordinasi terpadu.','Pengelola kerja sama','2026-10-31','DALAM PROSES','2026-10-04 15:51:07'),(5,2,'Masa berlaku','> H-180','E0','PKS berlaku 13 Juli 2026 s.d. 12 Juli 2029; tidak ada isu masa berlaku pada periode penilaian.','Pertahankan monitoring masa berlaku dan review berkala.','Pengelola kerja sama / PIC internal',NULL,'DALAM PROSES','2026-10-04 15:51:07'),(6,2,'Aktivitas/tenggat','MELEWATI TENGGAT','E1','Sebagian implementasi sudah berjalan dan konten telah tersedia di BESTI, tetapi belum seluruh ruang lingkup terlaksana.','Tuntaskan integrasi materi prioritas dan jadwalkan kegiatan narasumber/podcast/webinar.','PIC internal + PIC BNNP Kepri','2026-12-31','DALAM PROSES','2026-10-04 15:51:07'),(7,2,'Data/eviden','BELUM LENGKAP MASIH DALAM TENGGAT','E1','Evidence tersedia dari stakeholder, matriks ruang lingkup, P2MA, dan BESTI, tetapi masih tersebar dan belum terindeks.','Konsolidasikan satu repository evidence P02 dan susun indeks bukti per ruang lingkup.','PIC internal / Pengelola kerja sama','2026-10-31','DALAM PROSES','2026-10-04 15:51:07'),(8,2,'PIC','TIDAK AKTIF DENGAN PENGGANTI','E1','PIC mitra utama/cadangan tersedia dan PIC internal diasumsikan telah ditetapkan melalui SK; mekanisme update konten dan focal point Kanwil masih perlu ditegaskan.','Tetapkan alur koordinasi, focal point Kanwil, dan mekanisme persetujuan/update materi.','PIC internal + PIC BNNP Kepri','2026-10-31','DALAM PROSES','2026-10-04 15:51:07'),(9,3,'Masa berlaku','> H-180','E0','MoU berlaku 6 Januari 2026 s.d. 5 Januari 2031; masa berlaku tidak menjadi isu pada periode penilaian.','Pertahankan monitoring masa berlaku dan review berkala.','Pengelola kerja sama / PIC internal',NULL,'DALAM PROSES','2026-10-04 15:51:07'),(10,3,'Aktivitas/tenggat','MELEWATI TENGGAT','E1','Pelaksanaan aktif pada Posbankum, harmonisasi produk hukum, dan JDIH; AHU belum dilaksanakan dan data KI belum diperoleh.','Aktivasi tindak lanjut AHU dan klarifikasi/pelengkapan kegiatan KI.','Pengampu ruang lingkup + PIC Pemkot','2026-12-31','DALAM PROSES','2026-10-04 15:51:07'),(11,3,'Data/eviden','BELUM LENGKAP MASIH DALAM TENGGAT','E1','Terdapat 10 tautan bukti kegiatan dan evidence internal, tetapi penyimpanan masih tersebar dan cakupan evidence belum lengkap untuk seluruh ruang lingkup.','Konsolidasikan repository evidence P03 dan indeks per ruang lingkup/periode.','Pengelola kerja sama + unit pengampu','2026-10-31','DALAM PROSES','2026-10-04 15:51:07'),(12,3,'PIC','TIDAK AKTIF DENGAN PENGGANTI','E1','PIC mitra utama/cadangan sudah jelas dan koordinasi operasional berjalan. PIC internal individual lintas ruang lingkup belum terdokumentasi secara eksplisit.','Tegaskan focal point/PIC internal per ruang lingkup dan mekanisme koordinasi terpadu.','Pengelola kerja sama + unit pengampu','2026-10-31','DALAM PROSES','2026-10-04 15:51:07'),(13,4,'Masa berlaku','> H-180','E0','PKS berlaku 30 Juni 2026 s.d. 29 Juni 2029.','Pertahankan monitoring masa berlaku.','Pengelola kerja sama',NULL,'DALAM PROSES','2026-10-04 15:51:08'),(14,4,'Aktivitas/tenggat','MELEWATI TENGGAT','E1','Dua kegiatan awal tersedia, tetapi implementasi inti pada lima ruang lingkup masih terbatas.','Jalankan sosialisasi KI, fasilitasi pendaftaran, dan tindak lanjut Sentra KI.','PIC internal + PIC Bapperida','2026-12-31','DALAM PROSES','2026-10-04 15:51:08'),(15,4,'Data/eviden','BELUM LENGKAP MASIH DALAM TENGGAT','E1','Dua evidence kegiatan tersedia; data internal per ruang lingkup masih belum diperoleh.','Konsolidasikan repository dan sinkronkan data internal/mitra.','Pengelola + unit KI','2026-10-31','DALAM PROSES','2026-10-04 15:51:08'),(16,4,'PIC','TIDAK AKTIF DENGAN PENGGANTI','E1','PIC mitra sudah jelas; PIC internal formal dan pembagian peran perlu ditegaskan.','Konfirmasi PIC internal dan owner per ruang lingkup.','Pengelola kerja sama','2026-10-31','DALAM PROSES','2026-10-04 15:51:08'),(17,5,'Masa berlaku','> H-180','E0','MoU berlaku 19 Maret 2025 s.d. 18 Maret 2030.','Pertahankan monitoring masa berlaku.','Pengelola kerja sama',NULL,'DALAM PROSES','2026-10-04 15:51:08'),(18,5,'Aktivitas/tenggat','TIDAK ADA AKTIVITAS >180 HARI','E2','Implementasi terbukti pada pendidikan/KI, namun sebagian besar ruang lingkup belum aktif.','Susun kalender aktivasi penelitian, pengabdian, MBKM, kompetensi SDM dan JDIH.','PIC/pengampu P05','2026-12-31','DALAM PROSES','2026-10-04 15:51:08'),(19,5,'Data/eviden','BELUM LENGKAP MASIH DALAM TENGGAT','E1','Evidence KI/pendidikan tersedia, tetapi terdapat banyak versi data dan gap evidence pada ruang lingkup lain.','Rekonsiliasi versi dan konsolidasikan repository P05.','Pengelola + PIC','2026-10-31','DALAM PROSES','2026-10-04 15:51:08'),(20,5,'PIC','TIDAK AKTIF TANPA PENGGANTI','E2','PIC mitra sudah jelas; PIC internal dan rencana aksi terpadu belum tersedia.','Tetapkan PIC internal dan rencana aksi seluruh ruang lingkup.','Pengelola kerja sama','2026-10-31','DALAM PROSES','2026-10-04 15:51:08'),(21,6,'Masa berlaku','> H-180','E0','MoU berlaku 19 Maret 2025 s.d. 18 Maret 2030.','Pertahankan monitoring masa berlaku.','Pengelola kerja sama',NULL,'DALAM PROSES','2026-10-04 15:51:08'),(22,6,'Aktivitas/tenggat','TIDAK ADA AKTIVITAS >180 HARI','E2','Implementasi hanya terindikasi melalui bukti magang dan belum terverifikasi luas.','Verifikasi kegiatan yang pernah dilakukan dan susun kalender implementasi.','PIC/pengampu P06','2026-12-31','DALAM PROSES','2026-10-04 15:51:08'),(23,6,'Data/eviden','BELUM LENGKAP SETELAH TENGGAT','E2','Evidence sangat terbatas dan belum terkonsolidasi.','Bangun repository evidence dan lengkapi bukti kegiatan.','Pengelola + PIC','2026-10-31','DALAM PROSES','2026-10-04 15:51:08'),(24,6,'PIC','TIDAK AKTIF TANPA PENGGANTI','E2','PIC internal/mitra dan RTL belum terdokumentasi.','Tetapkan PIC dan rencana aksi formal.','Pengelola kerja sama','2026-10-31','DALAM PROSES','2026-10-04 15:51:08'),(25,7,'Masa berlaku','> H-180','E0','MoU berlaku 18 November 2025 s.d. 17 November 2030.','Pertahankan monitoring masa berlaku.','Pengelola kerja sama',NULL,'DALAM PROSES','2026-10-04 15:51:08'),(26,7,'Aktivitas/tenggat','TIDAK ADA AKTIVITAS >180 HARI','E2','Belum ada kegiatan bersama setelah >10 bulan.','Tetapkan dan laksanakan kegiatan prioritas pertama.','PIC/pengampu P07','2026-10-31','DALAM PROSES','2026-10-04 15:51:08'),(27,7,'Data/eviden','BELUM LENGKAP SETELAH TENGGAT','E2','Arsip/P2MA tersedia, tetapi evidence implementasi tidak ada.','Siapkan repository dan dokumentasikan bukti sejak kegiatan pertama.','Pengelola + PIC','2026-10-31','DALAM PROSES','2026-10-04 15:51:08'),(28,7,'PIC','TIDAK AKTIF TANPA PENGGANTI','E2','PIC dan rencana tindak lanjut belum ditetapkan.','Tetapkan PIC dan rencana aksi formal.','Pengelola kerja sama','2026-10-31','DALAM PROSES','2026-10-04 15:51:09'),(29,8,'Masa berlaku','> H-180','E0','MoU berlaku 18 November 2025 s.d. 17 November 2030.','Pertahankan monitoring masa berlaku.','Pengelola kerja sama',NULL,'DALAM PROSES','2026-10-04 15:51:09'),(30,8,'Aktivitas/tenggat','TIDAK ADA AKTIVITAS >180 HARI','E2','Baru satu kegiatan terbukti terlaksana; ruang lingkup lain belum aktif.','Jadwalkan implementasi prioritas dari 4 usulan tindak lanjut.','PIC internal + PIC Polibatam','2026-12-31','DALAM PROSES','2026-10-04 15:51:09'),(31,8,'Data/eviden','BELUM LENGKAP MASIH DALAM TENGGAT','E1','Evidence satu kegiatan dapat ditelusuri, tetapi repository keseluruhan belum lengkap.','Konsolidasikan repository evidence P08.','Pengelola + PIC','2026-10-31','DALAM PROSES','2026-10-04 15:51:09'),(32,8,'PIC','TIDAK AKTIF DENGAN PENGGANTI','E1','PIC mitra jelas dan usulan rinci; PIC internal belum terdokumentasi.','Tetapkan PIC internal/focal point dan alur koordinasi dengan Sentra HKI.','Pengelola kerja sama','2026-10-31','DALAM PROSES','2026-10-04 15:51:09'),(33,9,'Masa berlaku','> H-180','E0','MoU berlaku 8 Mei 2026 s.d. 7 Mei 2031.','Pertahankan monitoring masa berlaku.','Pengelola kerja sama',NULL,'DALAM PROSES','2026-10-04 15:51:09'),(34,9,'Aktivitas/tenggat','MELEWATI TENGGAT','E1','Belum ada kegiatan aktual; tujuh rencana mulai September–Oktober 2026 dan seterusnya.','Mulai realisasi prioritas pembentukan Sentra KI dan sosialisasi KI.','PIC internal + PIC STAI Natuna','2026-10-31','DALAM PROSES','2026-10-22 06:49:59'),(35,9,'Data/eviden','BELUM LENGKAP MASIH DALAM TENGGAT','E1','Data PIC dan rencana lengkap, tetapi evidence implementasi belum tersedia.','Siapkan repository dan indeks bukti sejak kegiatan pertama.','Pengelola + PIC','2026-10-31','DALAM PROSES','2026-10-04 15:51:09'),(36,9,'PIC','TIDAK AKTIF DENGAN PENGGANTI','E1','PIC mitra jelas; PIC internal belum terdokumentasi.','Tetapkan PIC internal dan jadwal koordinasi rutin.','Pengelola kerja sama','2026-10-31','DALAM PROSES','2026-10-04 15:51:09'),(37,10,'Masa berlaku','> H-180','E0','MoU berlaku 8 Mei 2026 s.d. 7 Mei 2031.','Pertahankan monitoring masa berlaku.','Pengelola kerja sama',NULL,'DALAM PROSES','2026-10-04 15:51:09'),(38,10,'Aktivitas/tenggat','MELEWATI TENGGAT','E1','Belum ada kegiatan aktual; masa implementasi masih <6 bulan.','Mulai satu kegiatan prioritas sebelum review berikutnya.','PIC/pengampu P10','2026-10-31','DALAM PROSES','2026-10-04 15:51:09'),(39,10,'Data/eviden','BELUM LENGKAP MASIH DALAM TENGGAT','E1','Evidence administratif ada, tetapi implementasi belum terdokumentasi.','Verifikasi arsip dan siapkan repository sejak awal.','Pengelola + PIC','2026-10-31','DALAM PROSES','2026-10-04 15:51:09'),(40,10,'PIC','TIDAK AKTIF DENGAN PENGGANTI','E1','PIC dan RTL belum tersedia.','Tetapkan PIC dan rencana aksi sebelum usia 6 bulan.','Pengelola kerja sama','2026-10-31','DALAM PROSES','2026-10-04 15:51:09'),(41,11,'Masa berlaku','> H-180','E0','PKS berlaku 19 Maret 2025 s.d 18 Maret 2030.','Pertahankan monitoring masa berlaku.','Pengelola kerja sama',NULL,'DALAM PROSES','2026-10-04 15:51:09'),(42,11,'Aktivitas/tenggat','NORMAL','E0','Dua kegiatan terlaksana: pencatatan 2 HKI cipta booklet dan pendaftaran merek paten logo PBC.','Lanjutkan sosialisasi & klinik pengajuan paten sederhana.','Sentra KI PBC + Kanwil','2026-12-31','DALAM PROSES','2026-10-04 15:51:09'),(43,11,'Data/eviden','LENGKAP','E0','Folder Google Drive bukti pencatatan HKI dan pemeriksaan draft paten tersedia.','Konsolidasikan repository digital naskah dan bukti.','Pengelola kerja sama','2026-10-31','DALAM PROSES','2026-10-04 15:51:10'),(44,11,'PIC','AKTIF','E0','PIC Sentra KI PBC aktif berkoordinasi dengan tim KI Kanwil.','Pertahankan koordinasi rutin.','Sentra KI PBC',NULL,'DALAM PROSES','2026-10-04 15:51:10'),(45,12,'Masa berlaku','> H-180','E0','MoU berlaku 20 April 2026 s.d 19 April 2031.','Monitoring berkala masa berlaku.','Pengelola kerja sama',NULL,'DALAM PROSES','2026-10-04 15:51:10'),(46,12,'Aktivitas/tenggat','BELUM DIPERIKSA','V0','Naskah tersedia; belum ada laporan kegiatan pasca-baseline.','Susun kalender aksi dan koordinasi kegiatan awal.','Pengelola + Mitra','2026-11-30','BELUM MULAI','2026-10-04 15:51:10'),(47,12,'Data/eviden','BELUM DIPERIKSA','V0','Naskah dan entri P2MA tersedia, bukti kegiatan belum terhimpun.','Siapkan repository bukti kegiatan.','Pengelola kerja sama','2026-10-31','BELUM MULAI','2026-10-04 15:51:10'),(48,12,'PIC','BELUM DIPERIKSA','V0','PIC pimpinan tercantum di MoU, PIC operasional belum dikonfirmasi tertulis.','Konfirmasi penunjukan PIC operasional.','Pengelola kerja sama','2026-10-31','BELUM MULAI','2026-10-04 15:51:10'),(49,13,'Masa berlaku','> H-180','E0','MoU berlaku 18 November 2025 s.d 17 November 2030.','Pertahankan pemantauan masa berlaku.','Pengelola kerja sama',NULL,'DALAM PROSES','2026-10-04 15:51:10'),(50,13,'Aktivitas/tenggat','NORMAL','E0','Tiga kegiatan terlaksana: tindak lanjut MoU, sharing session, dan pencatatan hak cipta.','Jadwalkan kuliah pakar dan pembentukan pos layanan hukum.','PIC UIS + Kanwil','2026-12-31','DALAM PROSES','2026-10-04 15:51:10'),(51,13,'Data/eviden','LENGKAP','E0','Tiga tautan Google Drive dan dokumen bukti kegiatan tersedia.','Konsolidasikan repositori terpadu.','Pengelola kerja sama','2026-10-31','DALAM PROSES','2026-10-04 15:51:10'),(52,13,'PIC','AKTIF','E0','PIC mitra aktif mengajukan usulan kuliah pakar dan klinik paten.','Tetapkan focal point Kanwil tetap.','Pengelola kerja sama','2026-10-31','DALAM PROSES','2026-10-04 15:51:10'),(53,14,'Masa berlaku','> H-180','E0','MoU berlaku 5 Desember 2025 s.d 4 Desember 2030.','Monitoring berkala masa berlaku.','Pengelola kerja sama',NULL,'DALAM PROSES','2026-10-04 15:51:10'),(54,14,'Aktivitas/tenggat','NORMAL','E0','Laporan pelaksanaan kemitraan tersedia melalui Google Docs terverifikasi.','Aktivasi pembentukan Sentra KI UNRIKA.','Pengelola + UNRIKA','2026-12-31','DALAM PROSES','2026-10-04 15:51:10'),(55,14,'Data/eviden','LENGKAP','E0','Dokumen laporan kemitraan terverifikasi pada Google Drive.','Pengarsipan bukti berkala.','Pengelola kerja sama','2026-10-31','DALAM PROSES','2026-10-04 15:51:10'),(56,14,'PIC','AKTIF','E0','PIC terhubung melalui koordinasi kegiatan Tri Dharma.','Konfirmasi SK PIC operasional tertulis.','Pengelola kerja sama','2026-10-31','DALAM PROSES','2026-10-04 15:51:10'),(57,15,'Masa berlaku','> H-180','E0','MoU berlaku 12 Maret 2026 s.d 11 Maret 2031.','Monitoring berkala masa berlaku.','Pengelola kerja sama',NULL,'DALAM PROSES','2026-10-04 15:51:10'),(58,15,'Aktivitas/tenggat','BELUM DIPERIKSA','V0','Naskah tersedia; belum ada kegiatan bersama pasca-baseline.','Susun rencana kegiatan edukasi KI dan bisnis.','Pengelola + Mitra','2026-11-30','BELUM MULAI','2026-10-04 15:51:10'),(59,15,'Data/eviden','BELUM DIPERIKSA','V0','Arsip naskah tersedia di P2MA; evidence kegiatan belum ada.','Siapkan repository eviden naskah.','Pengelola kerja sama','2026-10-31','BELUM MULAI','2026-10-04 15:51:10'),(60,15,'PIC','BELUM DIPERIKSA','V0','PIC operasional mitra belum ditunjuk resmi.','Minta surat penunjukan PIC mitra.','Pengelola kerja sama','2026-10-31','BELUM MULAI','2026-10-04 15:51:10'),(61,16,'Masa berlaku','> H-180','E0','PKS berlaku 1 Oktober 2026 s.d 30 September 2029 (3 tahun).','Monitoring berkala masa berlaku PKS turunan.','Pengelola kerja sama',NULL,'DALAM PROSES','2026-10-04 15:51:10'),(62,16,'Aktivitas/tenggat','NORMAL','E0','Rencana kerja sentra riset hukum maritim disetujui; kegiatan magang berjalan.','Pelaksanaan advokasi nelayan pesisir.','Fakultas Hukum UMRAH + Kanwil','2026-12-31','DALAM PROSES','2026-10-04 15:51:10'),(63,16,'Data/eviden','LENGKAP','E0','Naskah PKS dan laporan publikasi magang terverifikasi.','Konsolidasikan repository naskah turunan.','Pengelola kerja sama','2026-10-31','DALAM PROSES','2026-10-04 15:51:10'),(64,16,'PIC','AKTIF','E0','PIC Fakultas Hukum UMRAH dan Tim Pokja Kanwil aktif.','Pertahankan koordinasi rutin.','Pokja Kemitraan',NULL,'DALAM PROSES','2026-10-04 15:51:11'),(65,17,'Masa berlaku','> H-180','E0','PKS berlaku 1 September 2026 s.d 31 Agustus 2029 (3 tahun).','Monitoring masa berlaku PKS Sentra KI.','Pengelola kerja sama',NULL,'DALAM PROSES','2026-10-04 15:51:11'),(66,17,'Aktivitas/tenggat','NORMAL','E0','Rencana kerja inkubasi paten disetujui; pendampingan teknis berjalan.','Percepatan granted paten sederhana.','Sentra HKI Polibatam + Subbid KI','2026-12-31','DALAM PROSES','2026-10-04 15:51:11'),(67,17,'Data/eviden','LENGKAP','E0','Naskah PKS dan usulan pendampingan paten terintegrasi.','Pencatatan database paten.','Subbid Pelayanan KI','2026-10-31','DALAM PROSES','2026-10-04 15:51:11'),(68,17,'PIC','AKTIF','E0','Ketua Sentra HKI Polibatam dan Kasubbid Pelayanan KI aktif.','Rapat koordinasi berkala.','Subbid Pelayanan KI',NULL,'DALAM PROSES','2026-10-04 15:51:11'),(69,18,'Masa berlaku','> H-180','E0','Nota Kesepahaman berlaku 1 Januari 2027 s.d 31 Desember 2030 (4 tahun).','Monitoring masa berlaku MoU.','Pengelola kerja sama',NULL,'DALAM PROSES','2026-10-04 15:51:11'),(70,18,'Aktivitas/tenggat','NORMAL','E0','Rencana kerja penguatan literasi hukum dan desa sadar hukum disetujui.','Penyusunan petunjuk teknis pos bantuan hukum desa.','Bagian Hukum Bintan + Kanwil','2027-03-31','DALAM PROSES','2026-10-04 15:51:11'),(71,18,'Data/eviden','LENGKAP','E0','Draft dan naskah kesepakatan terverifikasi.','Dokumentasi arsip resmi.','Pengelola kerja sama','2026-12-31','DALAM PROSES','2026-10-04 15:51:11'),(72,18,'PIC','AKTIF','E0','Bagian Hukum Setda Bintan terkonfirmasi.','Penetapan SK tim kerja bersama.','Bagian Hukum Setda',NULL,'DALAM PROSES','2026-10-04 15:51:11');
