INSERT INTO `intervensi_usulan` VALUES (1,1,'Masih dapat diselesaikan pada level pengelola/unit pengampu','Gap utama bersifat tata kelola dan implementasi operasional; eskalasi pimpinan dilakukan jika penetapan PIC/aktivasi ruang lingkup tidak terselesaikan.','Arahan pimpinan untuk penetapan PIC formal dan aktivasi 3 ruang lingkup yang belum berjalan','2026-10-04 15:51:15'),(2,4,'Rapat PIC & koordinasi teknis bersama Bapperida Bintan','Belum ada isu material yang membutuhkan keputusan pimpinan; kebutuhan saat ini adalah aktivasi operasional dan penataan evidence.','Arahan tindak lanjut aktivasi operasional dan penataan evidence terpadu','2026-10-04 15:51:15'),(6,3,'Dapat diselesaikan pada level pengelola/unit pengampu','Belum terdapat isu material yang membutuhkan keputusan pimpinan. Gap utama bersifat operasional dan dapat ditangani melalui penguatan koordinasi, aktivasi AHU/KI, penataan evidence, dan pengukuran outcome.','Arahan pimpinan untuk penguatan koordinasi lintas instansi serta percepatan tindak lanjut layanan AHU dan KI','2026-10-04 15:51:15');
