INSERT INTO `mitra_kinerja` VALUES (1,'P01','Pilot Utama','Dewan Kerajinan Nasional Daerah Provinsi Kepulauan Riau','Peningkatan Perlindungan Kekayaan Intelektual Kriya, Wastra dan Fashion di Provinsi Kepulauan Riau','PKS','KI',NULL,'2025-11-15','2030-11-14','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Evlin','Unit pengampu, PIC internal/mitra, rencana tindak lanjut, eviden implementasi, dan hambatan belum memiliki dasar yang cukup. Kerja sama belum menunjukkan bukti operasional yang terstruktur pada cut-off.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,NULL,NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1787732310.pdf',NULL,1,'2026-09-22','SIAP DIVALIDASI','OUTCOME AWAL / IMPLEMENTASI TERBATAS','LANJUTKAN DENGAN AKTIVASI RUANG LINGKUP DAN PENGUATAN TATA KELOLA\n\nTemuan Utama:\nDibanding baseline, terdapat implementasi nyata pada edukasi KI dan pelayanan pendaftaran KI, beserta manfaat awal bagi UMKM/masyarakat. Namun tiga ruang lingkup belum memiliki data, PIC/rencana aksi belum jelas, dan evidence masih terbatas.\n\nRencana Tindak Lanjut:\n1) Tetapkan PIC internal dan mitra; 2) susun rencana aksi 5 ruang lingkup; 3) aktifkan KIK, penegakan KI, dan pertukaran data; 4) konsolidasikan evidence; 5) ukur penerima layanan/UMKM dan tindak lanjut pendaftaran KI; 6) review triwulanan.','2026-09-22 03:33:35','2026-10-22 06:50:49'),(2,'P02','Pilot Utama','Badan Narkotika Nasional Provinsi Kepulauan Riau','Integrasi dan Pemanfaatan Belajar Seru Tiap Hari Learning Hub sebagai Platform Pembelajaran Digital dalam Penguatan Literasi Hukum, Pencegahan Penyalahgunaan Narkotika, dan Pembangunan Karakter Generasi Muda di Provinsi Kepulauan Riau','PKS','P3H',NULL,'2026-07-13','2029-07-13','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Kompilasi Pokja Data','Gap utama berada pada tata kelola operasional dan aktivasi kerja sama: arsip resmi, pengampu, PIC, rencana aksi, kegiatan, dan eviden belum tersedia pada cut-off.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,NULL,NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1785760147.pdf',NULL,NULL,NULL,'MASA IMPLEMENTASI AWAL','OUTPUT AWAL / IMPLEMENTASI BERJALAN','LANJUTKAN IMPLEMENTASI DAN SIAPKAN PENGUKURAN HASIL\n\nTemuan Utama:\nSejak baseline, telah tersedia PIC mitra, rencana tindak lanjut, integrasi materi yang sedang berjalan, dan output awal berupa konten layanan hukum pada BESTI Learning Hub. Karena PKS baru berlaku sejak 13 Juli 2026, outcome dan kontribusi/dampak belum memasuki periode penilaian yang memadai.\n\nRencana Tindak Lanjut:\n1) Tegaskan focal point dan mekanisme update konten; 2) konsolidasikan repository evidence P02; 3) lanjutkan integrasi e-book/modul; 4) realisasikan kolaborasi narasumber/podcast/webinar; 5) mulai ukur konten, akses/pengguna, pemanfaatan dan umpan balik; 6) lakukan review outcome/kontribusi setelah periode implementasi memadai.','2026-09-22 03:33:35','2026-10-22 06:50:49'),(3,'P03','Pilot Utama','Pemerintah Kota Tanjungpinang','Pelayanan Hukum','MoU','AHU',NULL,'2026-01-06','2031-01-05','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Ischika','Gap utama berada pada arsip resmi, unit pengampu, PIC, rencana tindak lanjut, pelaksanaan, eviden, dan hambatan. Belum tersedia bukti yang cukup untuk menggambarkan implementasi.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,NULL,NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1778046924.pdf',NULL,NULL,NULL,'SIAP DIVALIDASI','OUTCOME AWAL / IMPLEMENTASI AKTIF','LANJUTKAN DENGAN PENGUATAN IMPLEMENTASI, EVIDENCE, DAN PENGUKURAN OUTCOME\n\nTemuan Utama:\nDibanding baseline, kerja sama telah berkembang menjadi implementasi aktif: 10 kegiatan mitra seluruhnya memiliki bukti; Posbankum, harmonisasi produk hukum, dan JDIH menunjukkan output serta manfaat awal. Gap utama adalah pemerataan implementasi pada AHU/KI, penegasan PIC internal, konsolidasi evidence, dan pengukuran outcome/kontribusi.\n\nRencana Tindak Lanjut:\n1) Tegaskan PIC/focal point internal per ruang lingkup; 2) konsolidasikan repository evidence P03; 3) lanjutkan pembinaan Posbankum, harmonisasi, dan JDIH; 4) aktivasi tindak lanjut AHU dan klarifikasi layanan KI; 5) ukur penerima layanan, jumlah harmonisasi, capaian JDIH, serta outcome layanan; 6) lakukan review triwulanan.','2026-09-22 03:33:35','2026-10-22 06:50:49'),(4,'P04','Pilot Utama','Badan Perencanaan Pembangunan, Riset, dan Inovasi Daerah Kabupaten Bintan','Pelindungan dan Pemanfaatan Kekayaan Intelektual','PKS','KI',NULL,'2026-06-30','2029-06-29','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Kompilasi Pokja Data','Unit pengampu/PIC belum memiliki dasar formal dan rencana tindak lanjut belum tersedia. Kerja sama belum bergerak ke pelaksanaan sehingga eviden implementasi belum terbentuk.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,'Diana Martin (Badan Perencanaan Pembangunan Riset dan Inovasi Daerah Kabupaten Bintan)',NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1785760267.pdf',NULL,1,'2026-09-23','MASA IMPLEMENTASI AWAL','OUTPUT AWAL / IMPLEMENTASI BERJALAN','LANJUTKAN IMPLEMENTASI AWAL DAN BANGUN BUKTI HASIL\n\nTemuan Utama:\nDibanding baseline, kini telah tersedia PIC mitra, 3 usulan tindak lanjut, 2 kegiatan dengan bukti, dan output awal. Namun kerja sama masih dalam masa implementasi awal dan implementasi inti KI belum merata.\n\nRencana Tindak Lanjut:\n1) Konfirmasi PIC internal; 2) lengkapi target 3 usulan tindak lanjut; 3) laksanakan sosialisasi KI dan fasilitasi pendaftaran; 4) siapkan arah pembentukan/penguatan Sentra KI; 5) konsolidasikan evidence; 6) kumpulkan indikator outcome untuk review berikutnya.','2026-09-22 03:33:35','2026-10-22 06:50:49'),(5,'P05','Pilot Utama','Sekolah Tinggi Agama Islam Negeri Sultan Abdurrahman Kepulauan Riau','Fasilitasi Tri Dharma Perguruan Tinggi dan Pelayanan Hukum','MoU','AHU',NULL,'2025-03-19','2030-03-18','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Nur\'ah Darina','Gap utama berada pada tata kelola operasional: unit pengampu, PIC internal/mitra, rencana tindak lanjut, pelaksanaan, eviden, dan hambatan belum terkonfirmasi.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,'Dr. Fadhila Yonata, M.Pd (STAIN Sultan Abdurrahman Kepri)',NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1758075052.pdf',NULL,NULL,NULL,'SIAP DIVALIDASI','OUTCOME AWAL / IMPLEMENTASI TERBATAS','LANJUTKAN DENGAN PERLUASAN IMPLEMENTASI DAN PENGUATAN TATA KELOLA\n\nTemuan Utama:\nDibanding baseline, sudah terdapat implementasi pada edukasi KI dan fasilitasi pendaftaran KI, termasuk 4 ciptaan tercatat dan satu pendaftaran baru yang sedang berjalan. Namun implementasi belum merata, tidak ada rencana tindak lanjut dari mitra, dan PIC internal/evidence lintas ruang lingkup masih perlu diperkuat.\n\nRencana Tindak Lanjut:\n1) Tetapkan PIC internal; 2) susun rencana aksi tahunan; 3) aktivasi penelitian, pengabdian, MBKM, kompetensi SDM dan JDIH; 4) lanjutkan fasilitasi KI dan pantau pendaftaran EC002026157468; 5) konsolidasikan evidence; 6) ukur outcome dan review triwulanan.','2026-09-22 03:33:35','2026-10-27 03:42:49'),(6,'P06','Pilot Utama','Universitas Maritim Raja Ali Haji (UMRAH)','Fasilitasi Tri Dharma Perguruan Tinggi dan Pelayanan Hukum','MoU','AHU',NULL,'2025-03-19','2030-03-18','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Kompilasi Pokja Data','Pelaksanaan masih belum terverifikasi secara utuh. Unit pengampu, PIC, rencana tindak lanjut, eviden formal, dan keterkaitan kegiatan dengan MoU merupakan gap utama pada cut-off.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,NULL,NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1758074583.pdf',NULL,NULL,NULL,'SIAP DIVALIDASI','IMPLEMENTASI SANGAT TERBATAS / TATA KELOLA BELUM KUAT','SEGERA BENTUK TATA KELOLA OPERASIONAL DAN AKTIFKAN IMPLEMENTASI\n\nTemuan Utama:\nDibanding baseline, belum terdapat tambahan evidence substantif. Jejak implementasi yang dapat ditelusuri masih terbatas pada sertifikat peserta magang, sementara PIC, RTL, outcome, dan kontribusi belum terbukti.\n\nRencana Tindak Lanjut:\n1) Tetapkan PIC; 2) verifikasi kegiatan magang/kegiatan lain; 3) susun rencana aksi tahunan; 4) aktifkan ruang lingkup prioritas; 5) konsolidasikan evidence; 6) ukur outcome; 7) review triwulanan.','2026-09-22 03:33:35','2026-10-22 06:50:49'),(7,'P07','Pilot Utama','Sekolah Tinggi Agama Islam Paduka Anambas','Pelayanan Hukum dan Fasilitasi Tri Dharma Perguruan Tinggi','MoU','AHU',NULL,'2025-11-18','2030-11-17','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Nadia Putri Boga','Gap utama adalah belum adanya tata kelola operasional dan aktivasi kerja sama. Karena belum ada kegiatan, eviden implementasi dan hasil juga belum terbentuk.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,NULL,NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1779175642.pdf',NULL,NULL,NULL,'SIAP DIVALIDASI','BELUM TERIMPLEMENTASI / TATA KELOLA OPERASIONAL BELUM TERBENTUK','AKTIFKAN KERJA SAMA SEGERA DAN BENTUK TATA KELOLA OPERASIONAL\n\nTemuan Utama:\nBelum ada perkembangan substantif dari baseline: belum terdapat PIC operasional, RTL, kegiatan, output, outcome, maupun evidence implementasi.\n\nRencana Tindak Lanjut:\n1) Tetapkan PIC internal/mitra; 2) pilih 1–2 ruang lingkup prioritas; 3) susun RTL dengan target 30–60 hari; 4) laksanakan kegiatan pertama; 5) bangun repository evidence; 6) review bulanan.','2026-09-22 03:33:35','2026-10-22 06:50:49'),(8,'P08','Pilot Utama','Politeknik Negeri Batam','Pelayanan Hukum dan Fasilitasi Tri Dharma Perguruan Tinggi','MoU','AHU',NULL,'2025-11-18','2030-11-17','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Kompilasi Pokja Data','Kerja sama belum dioperasionalkan. Gap utama berada pada pengampu/PIC, rencana aksi, pelaksanaan, eviden, dan identifikasi hambatan spesifik.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,NULL,NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1778058363.pdf',NULL,NULL,NULL,'SIAP DIVALIDASI','IMPLEMENTASI TERBATAS / RENCANA TINDAK LANJUT KUAT','PERCEPAT IMPLEMENTASI DAN TUNTASKAN TINDAK LANJUT PRIORITAS KI\n\nTemuan Utama:\nDibanding baseline, kini telah tersedia PIC mitra, satu kegiatan dengan bukti, dan empat usulan tindak lanjut yang sangat spesifik pada isu KI. Namun implementasi aktual masih terbatas dibanding luasnya ruang lingkup MoU.\n\nRencana Tindak Lanjut:\n1) Tetapkan PIC internal; 2) jadwalkan empat tindak lanjut KI; 3) pendampingan dokumen/pemeriksaan awal KI; 4) koordinasi isu tarif/prosedur dengan DJKI; 5) fasilitasi lisensi dan percepatan pemeriksaan paten; 6) mulai aktivasi ruang lingkup Tri Dharma lainnya; 7) ukur hasil dan konsolidasikan evidence.','2026-09-22 03:33:35','2026-10-22 06:50:49'),(9,'P09','Pilot Utama','Sekolah Tinggi Agama Islam Natuna','Pelayanan Hukum dan Fasilitasi Tri Dharma Perguruan Tinggi','MoU','AHU',NULL,'2026-05-08','2031-05-07','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Nur\'ah Darina','Gap utama mencakup tata kelola operasional, rencana aksi, pelaksanaan, eviden, serta kualitas metadata P2MA yang perlu ditindaklanjuti.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,'Dedi Supriadi, SE (STAI Natuna)',NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1779268941.pdf',NULL,NULL,NULL,'MASA IMPLEMENTASI AWAL','RENCANA IMPLEMENTASI TERSTRUKTUR / BELUM MULAI','MULAI IMPLEMENTASI SESUAI ROADMAP DAN BANGUN EVIDENCE SEJAK AWAL\n\nTemuan Utama:\nDibanding baseline, PIC mitra dan tujuh rencana tindak lanjut sudah tersedia dengan cukup rinci. Namun belum ada kegiatan aktual atau output, sehingga scorecard masih berada pada Masa Implementasi Awal.\n\nRencana Tindak Lanjut:\n1) Tetapkan PIC internal; 2) mulai pembentukan/penguatan Sentra KI; 3) laksanakan sosialisasi KI; 4) inventarisasi potensi KI; 5) buka klinik pendaftaran KI; 6) mulai program Hak Cipta/Merek prioritas; 7) siapkan SOP integrasi KI dengan penelitian/PkM; 8) dokumentasikan evidence dan review bulanan.','2026-09-22 03:33:35','2026-10-22 06:50:49'),(10,'P10','Pilot Utama','Sekolah Tinggi Ilmu Sosial dan Ilmu Politik Bunda Tanah Melayu','Pelayanan Hukum dan Fasilitasi Tri Dharma Perguruan Tinggi','MoU','AHU',NULL,'2026-05-08','2031-05-07','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Kompilasi Pokja Data','Gap utama adalah pembuktian arsip dan pengampu, penetapan PIC, penyusunan rencana aksi, serta belum adanya bukti pelaksanaan/eviden. Hambatan operasional juga belum terverifikasi.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,NULL,NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1778249973.pdf',NULL,NULL,NULL,'MASA IMPLEMENTASI AWAL','MASA IMPLEMENTASI AWAL / TATA KELOLA BELUM TERBENTUK','BENTUK TATA KELOLA DAN MULAI IMPLEMENTASI AWAL\n\nTemuan Utama:\nBelum ada perkembangan substantif dari baseline. Tata kelola operasional dan evidence implementasi belum terbentuk, tetapi usia kerja sama masih di bawah 6 bulan.\n\nRencana Tindak Lanjut:\n1) Tetapkan PIC internal/mitra; 2) susun RTL 3–6 bulan; 3) pilih kegiatan prioritas; 4) laksanakan kegiatan pertama; 5) siapkan repository evidence; 6) review setelah melewati 6 bulan.','2026-09-22 03:33:35','2026-10-22 06:50:49'),(11,'C01','Cadangan','Politeknik Bintan Cakrawala','Fasilitasi Tri Dharma Perguruan Tinggi dan Pelayanan Hukum','MoU','AHU',NULL,'2025-03-19','2030-03-18','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Kompilasi Pokja Data','Gap utama berada pada arsip resmi, pengampu, PIC, rencana tindak lanjut, pelaksanaan, eviden, dan hambatan. Belum ada dasar cukup untuk menyatakan implementasi telah berjalan.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,'Indah Andesta, S.Par., M.Sc (Politeknik Bintan Cakrawala)',NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1758074830.pdf',NULL,NULL,NULL,'BELUM LENGKAP','BELUM DAPAT DITENTUKAN','BELUM DITENTUKAN','2026-09-22 03:33:35','2026-10-27 03:42:49'),(12,'C02','Cadangan','Sekolah Tinggi Ilmu Tarbiyah (STIT) Mumtaz Karimun','Pelayanan Hukum dan Fasilitasi Tri Dharma Perguruan Tinggi','MoU','AHU',NULL,'2026-04-20','2031-04-19','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Kompilasi Pokja Data','Gap utama adalah belum selesainya pembuktian unsur operasional dan arsip. Ketercarian nama mitra di P2MA juga perlu dicatat sebagai isu pencarian, bukan sebagai ketidaksinkronan naskah.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,NULL,NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1778059603.pdf',NULL,NULL,NULL,'BELUM LENGKAP','BELUM DAPAT DITENTUKAN','BELUM DITENTUKAN','2026-09-22 03:33:35','2026-10-27 03:42:49'),(13,'C03','Cadangan','Universitas Ibnu Sina','Pelayanan Hukum dan Fasilitasi Tri Dharma Perguruan Tinggi','MoU','AHU',NULL,'2025-11-18','2030-11-17','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Nadia Putri Boga','Gap utama adalah belum terbentuknya tata kelola dan pelaksanaan operasional. Karena belum ada kegiatan, eviden implementasi dan output juga belum tersedia.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,'Amirullah (Bidang Kerja Sama)',NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1778056915.pdf',NULL,NULL,NULL,'SIAP DIVALIDASI','BELUM DAPAT DITENTUKAN','BELUM DITENTUKAN','2026-09-22 03:33:35','2026-10-27 03:42:56'),(14,'C04','Cadangan','Universitas Riau Kepulauan','Pelayanan Hukum dan Fasilitasi Tri Dharma Perguruan Tinggi','MoU','AHU',NULL,'2025-11-18','2030-11-17','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Kompilasi Pokja Data','Gap utama berada pada pengampu/PIC, rencana tindak lanjut, validasi laporan, pelaksanaan operasional, dan eviden implementasi. Karena keterkaitan laporan belum terbukti, pelaksanaan tetap belum terverifikasi.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,'Ajeng Handayani Purwaningrum, B.Ec., M.B.A (Kerjasama)',NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1778057000.pdf',NULL,NULL,NULL,'BELUM LENGKAP','BELUM DAPAT DITENTUKAN','BELUM DITENTUKAN','2026-09-22 03:33:35','2026-10-22 06:50:49'),(15,'C05','Cadangan','Sekolah Tinggi Ilmu Ekonomi Cakrawala','Pelayanan Hukum dan Fasilitasi Tri Dharma Perguruan Tinggi','MoU','AHU',NULL,'2026-03-12','2031-03-11','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Nur\'ah Darina','Gap utama berada pada tata kelola dan implementasi operasional, terutama arsip resmi, pengampu/PIC, rencana aksi, kegiatan, dan eviden.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,NULL,NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1778060172.pdf',NULL,NULL,NULL,'BELUM LENGKAP','BELUM DAPAT DITENTUKAN','BELUM DITENTUKAN','2026-09-22 03:33:35','2026-10-22 06:50:49'),(16,'P11','Pilot Utama','Universitas Maritim Raja Ali Haji (UMRAH)','Fasilitasi Sentra Riset Hukum Maritim & Pos Bantuan Hukum Masyarakat Pesisir','PKS','P3H',6,'2026-10-01','2029-09-30','TERVERIFIKASI',4,'DALAM PROSES',NULL,1,'Pemeriksa Kerja Sama','Verifikasi kondisi awal 12 elemen sedang berjalan.','2026-08-28','Gate 0 Promoted',NULL,NULL,NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1758074583.pdf',NULL,NULL,NULL,'BELUM LENGKAP','BELUM DAPAT DITENTUKAN','BELUM DITENTUKAN','2026-09-23 03:55:13','2026-10-04 15:49:25'),(17,'P12','Pilot Utama','Politeknik Negeri Batam - Sentra KI','Inkubasi Paten dan Desain Industri Kampus Vokasi','PKS','KI',8,'2026-09-01','2029-08-31','TERVERIFIKASI',4,'DALAM PROSES',NULL,NULL,'Pemeriksa Kerja Sama','Verifikasi kondisi awal 12 elemen sedang berjalan.','2026-09-23','Gate 0 Promoted',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'BELUM LENGKAP','BELUM DAPAT DITENTUKAN','BELUM DITENTUKAN','2026-09-23 04:55:30','2026-10-04 15:49:25'),(18,'P13','Pilot Utama','Pemerintah Kabupaten Bintan','Penguatan Literasi Hukum dan Layanan Terpadu Desa Sadar Hukum','MoU','AHU',NULL,'2027-01-01','2030-12-31','TERVERIFIKASI',4,'DALAM PROSES',NULL,NULL,'Pemeriksa Kerja Sama','Verifikasi kondisi awal 12 elemen sedang berjalan.','2026-09-23','Gate 0 Promoted',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'BELUM LENGKAP','BELUM DAPAT DITENTUKAN','BELUM DITENTUKAN','2026-09-23 05:21:55','2026-09-23 12:45:54');
/*!40000 ALTER TABLE `mitra_kinerja` ENABLE KEYS */;
