INSERT INTO `rencana_kerja` VALUES (1,4,'Rencana Kerja Fasilitasi dan Pendaftaran Kekayaan Intelektual Daerah Bintan','Inventarisasi potensi KI komunal, pendampingan pendaftaran merk UMKM binaan, dan sosialisasi hukum','Meningkatkan kesadaran hukum dan jumlah permohonan pendaftaran kekayaan intelektual di Kabupaten Bintan','2026-07-01','2027-06-30','Disetujui','Rencana kerja disetujui pimpinan; tindaklanjuti dan laporkan perkembangan secara berkala',NULL,'2026-09-23 03:51:03'),(2,16,'Rencana Kerja Fasilitasi Sentra Riset Hukum Maritim & Pos Bantuan Hukum Masyarakat Pesisir','Penyuluhan hukum, riset kebijakan maritim, dan klinik konsultasi hukum keliling','Mendekatkan akses keadilan dan pendampingan hukum pro-bono bagi masyarakat nelayan pesisir Kepulauan Riau','2026-10-01','2029-09-30','Disetujui','Disetujui otomatis melalui kelayakan Gate 0',NULL,'2026-09-23 03:55:13'),(3,17,'Rencana Kerja Inkubasi Paten dan Desain Industri Kampus Vokasi','','Mendorong hilirisasi riset terapan kampus vokasi ke pendaftaran paten resmi','2026-09-01','2029-08-31','Disetujui','Disetujui otomatis melalui kelayakan Gate 0',NULL,'2026-09-23 04:55:30'),(4,18,'Rencana Kerja Penguatan Literasi Hukum dan Layanan Terpadu Desa Sadar Hukum','Pelatihan paralegal dan sosialisasi peraturan','Membentuk desa binaan sadar hukum di pesisir','2027-01-01','2030-12-31','Disetujui','Disetujui otomatis melalui kelayakan Gate 0',NULL,'2026-09-23 05:21:55'),(5,2,'Integrasi Materi Pembelajaran E-Book & Modul Literasi Hukum pada BESTI Learning Hub','Integrasi e-book/modul literasi digital, edukasi hukum, kesadaran hukum, dan kekayaan intelektual','Meningkatkan literasi hukum dan pencegahan narkoba melalui platform digital','2026-09-01','2027-08-31','Disetujui','Disetujui berdasarkan tindak lanjut PKS BNN Kepri',NULL,'2026-09-23 16:46:08'),(6,2,'Kolaborasi Konten Edukasi Hukum & Pencegahan Narkoba (Podcast & Live Streaming)','Podcast bersama, webinar edukasi hukum, dan kampanye publik terpadu','Penyebarluasan informasi hukum dan bahaya narkoba bagi generasi muda Kepri','2026-10-01','2027-03-31','Disetujui','Sesuai kesepakatan rapat penguatan PIC',NULL,'2026-09-23 16:46:08'),(7,8,'Fasilitasi dan Pendampingan Pengurusan Kekayaan Intelektual Produk Hilirisasi Kampus Vokasi','Pemeriksaan substantif awal, pendampingan penyusunan spesifikasi paten, koreksi dokumen penolakan','Percepatan pendaftaran dan perolehan granted paten produk inovasi Polibatam','2026-10-01','2026-12-31','Disetujui','Usulan prioritas Sentra HKI Polibatam',NULL,'2026-09-23 16:46:08'),(8,8,'Pendampingan Teknis dan Lisensi Komersialisasi Kekayaan Intelektual Granted','Workshop lisensi, drafting perjanjian royalti, pendampingan komersialisasi ke industri','Menjadikan KI kampus memiliki nilai ekonomi dan daya serap industri','2026-11-01','2027-02-28','Disetujui','Mendukung program Merdeka Belajar Kampus Berdampak',NULL,'2026-09-23 16:46:08'),(9,9,'Pembentukan dan Penguatan Sentra Kekayaan Intelektual (Sentra KI) STAI/IAI Natuna','Penetapan struktur organisasi, tata kerja, sosialisasi dosen/mahasiswa, klinik pendaftaran','Membangun ekosistem perlindungan KI di wilayah perbatasan utara Natuna','2026-09-15','2027-09-14','Disetujui','Tindak lanjut MoU penguatan Tri Dharma wilayah perbatasan',NULL,'2026-09-23 16:46:08'),(10,9,'Klinik dan Fasilitasi Pendaftaran Hak Cipta & Merek Berbasis Khazanah Melayu Natuna','Inventarisasi karya buku, modul, karya budaya, dan merek produk lokal Natuna','Perlindungan hukum atas karya intelektual dan kekayaan komunal Natuna','2026-11-01','2026-12-31','Disetujui','Prioritas pelindungan budaya perbatasan',NULL,'2026-09-23 16:46:08'),(11,5,'Peningkatan Literasi Hukum dan Penguatan Tri Dharma Perguruan Tinggi Perbatasan','Penyuluhan hukum sivitas akademika, klinik konsultasi hukum, dan pembinaan desa sadar hukum','Mewujudkan kesadaran hukum masyarakat kampus dan perbatasan Bintan-Tanjungpinang','2026-09-01','2027-08-31','Disetujui','Kesepakatan bersama STAIN SAR Kepri',NULL,'2026-09-23 16:46:08'),(12,11,'Sosialisasi dan Klinik Pengajuan Paten Sederhana Sivitas Akademika','Bimbingan teknis drafting paten sederhana, inventarisasi invensi dosen dan mahasiswa','Peningkatan jumlah permohonan paten terdaftar dari kampus Politeknik Bintan Cakrawala','2026-10-01','2026-12-31','Disetujui','Tindak lanjut rapat penguatan Sentra KI',NULL,'2026-09-23 16:46:08'),(13,13,'Kuliah Pakar dan Pembentukan Pusat Konsultasi Layanan Hukum Terpadu','Kuliah umum berkala oleh narasumber Kanwil, pos aduan konsultasi hukum dan pendaftaran hak cipta','Edukasi hukum mahasiswa dan masyarakat sekitar kampus Batam','2026-09-01','2027-08-31','Disetujui','Sesuai usulan stakeholder Universitas Ibnu Sina',NULL,'2026-09-23 16:46:08'),(14,1,'Pelindungan dan Inventarisasi Kekayaan Intelektual Komunal Wastra dan Kriya Kepri','Pendataan motif batik/tenun Kepri, pendaftaran hak cipta dan merek kolektif pengrajin','Pemberdayaan ekonomi pengrajin lokal melalui kepastian hukum hak kekayaan intelektual','2025-11-15','2026-11-14','Disetujui','Implementasi PKS Dekranasda 2025-2030',NULL,'2026-09-23 16:46:08'),(15,3,'Pelayanan Hukum Terpadu dan Pembinaan Kelurahan Sadar Hukum Kota Tanjungpinang','Konsultasi hukum gratis, sosialisasi peraturan daerah, mediasi non-litigasi tingkat kelurahan','Meningkatkan kesadaran hukum masyarakat ibukota provinsi','2026-01-06','2027-01-05','Disetujui','Nota Kesepakatan Pemda Tanjungpinang',NULL,'2026-09-23 16:46:08'),(16,6,'Klinik Advokasi Hukum Nelayan Pesisir dan Sentra Riset Hukum Maritim','Konsultasi hukum keliling pulau, riset regulasi kelautan dan perikanan, pengabdian masyarakat','Mendekatkan keadilan hukum bagi nelayan tradisional Kepulauan Riau','2025-10-01','2026-09-30','Disetujui','Nota Kesepahaman UMRAH',NULL,'2026-09-23 16:46:08'),(17,4,'Sosialisasi Pendaftaran HAKI','Hasil Produk  yan ada dapat didaftarkan HAKI | Pelibatan: OPD, Masyarakat, UMKM dan  Pelaku inovasi','Diusulkan dari instrumen stakeholder','2026-09-01','2027-12-31','Disetujui',NULL,NULL,'2026-09-28 03:44:12'),(18,4,'Konsultasi Produk Hukum','Rencana aksi tindak lanjut kerja sama','Diusulkan dari instrumen stakeholder','2026-09-01','2027-12-31','Disetujui',NULL,NULL,'2026-09-28 03:44:12'),(19,4,'Fasilitasi Pendaftaran Terkait Kekayaan Intelektual','Rencana aksi tindak lanjut kerja sama','Diusulkan dari instrumen stakeholder','2026-09-01','2027-12-31','Disetujui',NULL,NULL,'2026-09-28 03:44:12'),(20,9,'Pembentukan/Penguatan Sentra Kekayaan Intelektual (Sentra KI) STAI/IAI Natuna melalui penetapan struktur, tugas, fungsi, dan mekanisme kerja','Tersedianya kelembagaan Sentra KI yang memiliki struktur dan tata kelola yang jelas sebagai pusat layanan KI kampus | Bantuan: Pendampingan kelembagaan, contoh struktur/tata kelola Sentra KI, dan konsultasi dari Kanwil Kemenkum Kepri. | Pelibatan: Pimpinan IAI/STAI Natuna, P3M/LPPM, Kanwil Kemenkum Kepri','Diusulkan dari instrumen stakeholder','2026-09-01','2027-12-31','Disetujui',NULL,NULL,'2026-09-28 03:44:13'),(21,9,'Sosialisasi dan edukasi Kekayaan Intelektual bagi dosen, mahasiswa, tenaga kependidikan, dan pengelola Sentra KI.','Meningkatnya pemahaman sivitas akademika tentang Hak Cipta, Merek, Paten, Desain Industri, KI Komunal, dan bentuk KI lainnya. | Bantuan: Narasumber, materi sosialisasi, dan layanan konsultasi KI. | Pelibatan: Kanwil Kemenkum Kepri, Sentra KI, dosen, mahasiswa','Diusulkan dari instrumen stakeholder','2026-09-01','2027-12-31','Disetujui',NULL,NULL,'2026-09-28 03:44:13'),(22,9,'Inventarisasi dan pemetaan potensi Kekayaan Intelektual yang dihasilkan dosen dan mahasiswa, termasuk karya penelitian, buku, modul, media pembelajaran, aplikasi, produk inovasi, dan karya seni/budaya Melayu.','Tersusunnya database potensi KI sivitas akademika yang dapat diprioritaskan untuk perlindungan hukum. | Bantuan: Pendampingan identifikasi jenis KI dan instrumen pemetaan. | Pelibatan: Sentra KI, P3M/LPPM, program studi, dosen, mahasiswa','Diusulkan dari instrumen stakeholder','2026-09-01','2027-12-31','Disetujui',NULL,NULL,'2026-09-28 03:44:13'),(23,9,'Klinik/Pendampingan Pendaftaran KI bagi sivitas akademika melalui Sentra KI secara berkala.','Meningkatnya jumlah karya dosen dan mahasiswa yang tercatat/terdaftar sebagai KI serta meningkatnya budaya perlindungan karya akademik. | Bantuan: Pendampingan teknis pendaftaran, konsultasi dokumen, dan fasilitasi layanan KI. | Pelibatan: Kanwil Kemenkum Kepri, Sentra KI, pemilik karya','Diusulkan dari instrumen stakeholder','2026-09-01','2027-12-31','Disetujui',NULL,NULL,'2026-09-28 03:44:13'),(24,9,'Program prioritas pendaftaran Hak Cipta dan Merek atas karya unggulan institusi dan sivitas akademika.','Tersedianya sejumlah sertifikat pencatatan Hak Cipta dan/atau pendaftaran Merek sebagai luaran nyata implementasi MoU. | Bantuan: Verifikasi karya dan pendampingan proses pengajuan KI. | Pelibatan: Sentra KI, Kanwil Kemenkum Kepri, P3M/LPPM, unit terkait','Diusulkan dari instrumen stakeholder','2026-09-01','2027-12-31','Disetujui',NULL,NULL,'2026-09-28 03:44:13'),(25,9,'Pengembangan KI berbasis Khazanah Melayu dan potensi lokal Natuna, termasuk dokumentasi dan perlindungan karya budaya/pengetahuan tradisional yang relevan.','Terlindunginya potensi kekayaan intelektual lokal serta meningkatnya kontribusi kampus dalam pelestarian dan pengembangan Khazanah Melayu Natuna. | Bantuan: Pendampingan identifikasi KI Komunal dan konsultasi perlindungan KI. | Pelibatan: IAI/STAI Natuna, Kanwil Kemenkum Kepri, pemerintah daerah, masyarakat/adat','Diusulkan dari instrumen stakeholder','2026-09-01','2027-12-31','Disetujui',NULL,NULL,'2026-09-28 03:44:13'),(26,11,'Sosialisasi dan Klinik Pengajuan Paten Sederhana','1. Dosen mengerti bagaimana untuk mengajukan paten sederhana,\n2. Produk-produk yang dapat diakui sebagai paten sederhana, | Bantuan: Narasumber terkait Paten Sederhana | Pelibatan: Kanwil Kemenkum Kepri + Sentra KI PBC + Dosen PBC','Diusulkan dari instrumen stakeholder','2026-09-01','2027-12-31','Disetujui',NULL,NULL,'2026-09-28 03:44:14'),(27,11,'Penguatan Kapasitas Pengelola Sentra KI PBC','Meningkatnya kemampuan tim Sentra KI dalam memberikan layanan informasi, identifikasi, pendampingan, dan administrasi KI | Bantuan: Narasumber, pelatihan, dan pendampingan pengelola | Pelibatan: Kanwil Kemenkum Kepri + Sentra KI PBC','Diusulkan dari instrumen stakeholder','2026-09-01','2027-12-31','Disetujui',NULL,NULL,'2026-09-28 03:44:14'),(28,11,'Kanwil Kemenkum Kepri + Sentra KI PBC','Terbangunnya budaya perlindungan KI yang terintegrasi dalam kegiatan pendidikan, penelitian, dan PkM | Bantuan: Pendampingan program dan materi KI | Pelibatan: Kanwil Kemenkum Kepri + Pimpinan/P3M PBC','Diusulkan dari instrumen stakeholder','2026-09-01','2027-12-31','Disetujui',NULL,NULL,'2026-09-28 03:44:14'),(29,13,'kegiatan pertemuan  dan evaluasi dengan kumham','kerja sama dan implemntasi yang berkelanjutan dan berdampak | Bantuan: suport dana dan sharing dana kegiatan evaluasi | Pelibatan: kemenkumham dan civitas akademika UIS','Diusulkan dari instrumen stakeholder','2026-09-01','2027-12-31','Disetujui',NULL,NULL,'2026-09-28 03:44:14'),(30,13,'Kegiatan kuliah pakar','edukasi hukum kepada mahasiswa UIS | Bantuan: Nara sumber dari kumham | Pelibatan: mahasiswa dan dosen','Diusulkan dari instrumen stakeholder','2026-09-01','2027-12-31','Disetujui',NULL,NULL,'2026-09-28 03:44:14'),(31,13,'pusat layanan hukum dan hak cipta khusus untuk UIS sebagai mitra yang telah bekerja sama','layanan dan pusat aduan dan hukum terkait hakcipta | Bantuan: pakar hukum dari kumham | Pelibatan: seluruh civitas akademika UIS','Diusulkan dari instrumen stakeholder','2026-09-01','2027-12-31','Disetujui',NULL,NULL,'2026-09-28 03:44:15'),(32,13,'sosialisasi, Worshop atau pelatihan terkait Paten dan Paten sederhana','menghasilkan paten dari hasil penelitian dan pengabdian dosen | Bantuan: narasumber dari kumham | Pelibatan: dosen dilingkungan UIS','Diusulkan dari instrumen stakeholder','2026-09-01','2027-12-31','Disetujui',NULL,NULL,'2026-09-28 03:44:15'),(33,7,'Rencana Kerja Penguatan Tri Dharma Perguruan Tinggi dan Pembinaan Hukum Perbatasan Kepulauan Anambas','Penyuluhan hukum maritim, pembinaan desa sadar hukum, dan fasilitasi pendaftaran kekayaan intelektual','Mewujudkan kesadaran hukum masyarakat dan perlindungan hak cipta di wilayah 3T Kepulauan Anambas','2025-11-18','2026-11-17','Disetujui','Implementasi Nota Kesepahaman STAI Paduka Anambas 2025-2030',NULL,'2026-10-04 15:50:35'),(34,10,'Rencana Kerja Tri Dharma Perguruan Tinggi, Magang Mahasiswa, dan Diseminasi Hukum Kemaritiman','Magang mahasiswa, penelitian bersama bidang kebijakan publik, dan diseminasi informasi hukum','Penguatan kompetensi praktisi hukum dan tata kelola kebijakan publik di Kota Batam','2026-05-08','2027-05-07','Disetujui','Implementasi Nota Kesepahaman STISIP Bunda Tanah Melayu 2026-2031',NULL,'2026-10-04 15:50:35'),(35,12,'Rencana Kerja Literasi Hukum Islam, Pembinaan Kesadaran Hukum, dan Tri Dharma Perguruan Tinggi','Penyuluhan hukum terpadu, klinik konsultasi hukum keluarga/keperdataan, dan pengabdian masyarakat','Meningkatkan literasi hukum masyarakat Kabupaten Karimun berbasis sinergi kampus keagamaan','2026-04-20','2027-04-19','Disetujui','Implementasi Nota Kesepahaman STIT Mumtaz Karimun 2026-2031',NULL,'2026-10-04 15:50:35'),(36,14,'Rencana Kerja Fasilitasi Sentra Kekayaan Intelektual dan Penguatan Tri Dharma Perguruan Tinggi UNRIKA','Pendampingan pendaftaran hak cipta dan paten dosen/mahasiswa, klinik KI, dan kuliah umum hukum','Peningkatan pendaftaran kekayaan intelektual sivitas akademika Universitas Riau Kepulauan','2025-12-05','2026-12-04','Disetujui','Implementasi Nota Kesepahaman UNRIKA 2025-2030',NULL,'2026-10-04 15:50:35'),(37,15,'Rencana Kerja Edukasi Hak Cipta, Pendampingan Inovasi Bisnis, dan Penguatan Tri Dharma Kampus','Edukasi kekayaan intelektual bagi mahasiswa ekonomi, perlindungan merek bisnis rintisan, dan seminar','Menumbuhkan budaya perlindungan kekayaan intelektual pada sektor bisnis kreatif di Batam','2026-03-12','2027-03-11','Disetujui','Implementasi Nota Kesepahaman STIE Cakrawala 2026-2031',NULL,'2026-10-04 15:50:35');
