INSERT INTO `validasi` VALUES (1,1,'BELUM',NULL,NULL,'Penilaian menggunakan Final Baseline P01, data internal per ruang lingkup, dan file dekranasda.xlsx sebagai evidence tambahan. PKS telah berjalan lebih dari 6 bulan sehingga seluruh I1–I7 dinilai.'),(2,2,'BELUM',NULL,NULL,'Contoh pengisian berdasarkan final baseline, data mitra, data internal per ruang lingkup, dan asumsi SK PIC internal tersedia. I4 Outcome dan I5 Kontribusi/Dampak belum dinilai karena PKS baru berjalan sekitar 2,5 bulan.'),(3,3,'BELUM',NULL,NULL,'Penilaian menggunakan Final Baseline P03, data internal per ruang lingkup, dan data yang diisi Pemerintah Kota Tanjungpinang. MoU telah berjalan lebih dari 6 bulan sehingga seluruh I1–I7 dinilai. Skor tetap memerlukan validasi reviewer/validator.'),(4,4,'BELUM',NULL,NULL,'Penilaian menggunakan Final Baseline P04, data internal per ruang lingkup, dan baperida.xlsx sebagai evidence tambahan. PKS baru 89 hari, sehingga I4 Outcome dan I5 Kontribusi/Dampak belum dinilai.'),(5,5,'BELUM',NULL,NULL,'Penilaian menggunakan Final Baseline P05, data internal per ruang lingkup, dan stain sar.xlsx sebagai evidence tambahan. MoU telah berjalan lebih dari 6 bulan sehingga seluruh I1–I7 dinilai.'),(6,6,'BELUM',NULL,NULL,'Penilaian menggunakan Final Baseline P06 dan form evidence P06 yang masih belum terisi substantif. Karena MoU >6 bulan, seluruh I1–I7 dinilai.'),(7,7,'BELUM',NULL,NULL,'Penilaian menggunakan Final Baseline P07 dan form evidence P07 yang masih kosong. Karena MoU >6 bulan, seluruh I1–I7 dinilai.'),(8,8,'BELUM',NULL,NULL,'Penilaian menggunakan Final Baseline P08 dan polibatam.xlsx sebagai evidence terbaru. MoU sudah >6 bulan sehingga seluruh I1–I7 dinilai.'),(9,9,'BELUM',NULL,NULL,'Penilaian menggunakan Final Baseline P09 dan stai natuna.xlsx sebagai evidence terbaru. MoU baru 142 hari; I2–I5 belum dinilai karena implementasi belum dimulai.'),(10,10,'BELUM',NULL,NULL,'Penilaian menggunakan Final Baseline P10 dan form evidence P10 yang belum terisi. Karena MoU baru 142 hari, I2–I5 = BELUM DAPAT DINILAI.'),(11,11,'BELUM',NULL,NULL,'Penilaian naskah kemitraan Politeknik Bintan Cakrawala (PBC) berbasis portofolio cadangan C01/C02 dan data stakeholder.'),(12,12,'BELUM',NULL,NULL,'Penilaian naskah kemitraan STIT Mumtaz Karimun berbasis naskah MoU dan verifikasi P2MA.'),(13,13,'BELUM',NULL,NULL,'Penilaian naskah kemitraan Universitas Ibnu Sina (UIS) berbasis data stakeholder pelaksanaan MoU dan pencatatan hak cipta.'),(14,14,'BELUM',NULL,NULL,'Penilaian naskah kemitraan Universitas Riau Kepulauan (UNRIKA) berbasis laporan pelaksanaan kemitraan.'),(15,15,'BELUM',NULL,NULL,'Penilaian naskah kemitraan STIE Cakrawala berbasis verifikasi naskah MoU pada P2MA.'),(16,16,'BELUM',NULL,NULL,'Penilaian naskah PKS turunan UMRAH bidang kemaritiman dan advokasi hukum pesisir.'),(17,17,'BELUM',NULL,NULL,'Penilaian naskah PKS turunan Politeknik Negeri Batam Sentra Kekayaan Intelektual.'),(18,18,'BELUM',NULL,NULL,'Penilaian Nota Kesepahaman induk Pemerintah Kabupaten Bintan bidang literasi dan pembinaan hukum.');
